// statusLabel is Radarr's Status fact: the file's state in words.
func statusLabel(li projection.LibraryItem) string {
	switch projection.LibraryStatus(li) {
	case "deleting":
		if li.DeleteError != "" {
			return "Delete failed: " + li.DeleteError
		}
		return "Deleting"
	case "cutoff-unmet":
		return "Cutoff Unmet"
	case "downloaded":
		if li.Phase == "Transcoded" {
			return "Transcoded"
		}
		return "Downloaded"
	case "downloading":
		return "Downloading"
	case "unmonitored":
		// A series with nothing on disk and nothing wanted. A movie keeps
		// Radarr's word for an unmonitored item without a file, Missing.
		if li.Kind == commonv1.MediaKindSeries {
			return "Unmonitored"
		}
		return "Missing"
	default:
		return "Missing"
	}
}

// totalSize is the size of the item's files together.
func totalSize(files []FileRow) int64 {
	var total int64
	for _, f := range files {
		total += f.SizeBytes
	}
	return total
}

